[MenuItem("Anseong/Art/Export Factory Paving")]
public static void ExportFactoryPaving(){EditorSceneManager.OpenScene(Scene);var root=GameObject.Find("Factory_HighlightedLZone");var plan=new SurfacePlan();foreach(var t in root.GetComponentsInChildren<Transform>()){if(!t.gameObject.activeInHierarchy||!PrefabUtility.IsOutermostPrefabInstanceRoot(t.gameObject))continue;var path=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject);int type=path.Contains("Warehouse")||path.Contains("StorageSilo")?4:path.Contains("RollingMill")||path.Contains("SteelmakingHall")?1:path.Contains("BlastFurnace")||path.Contains("GasCleaning")?2:path.Contains("Utility")||path.Contains("Pump")?3:-1;if(type<0)continue;var b=B(t.gameObject);if(b.size.x<8||b.size.z<8)continue;plan.areas.Add(ZoneBox(type,b,7));}Directory.CreateDirectory("Tools/FactoryPavingDesign");File.WriteAllText("Tools/FactoryPavingDesign/factory_paving_plan.json",JsonUtility.ToJson(plan));Debug.Log("FACTORY_PAVING_PLAN patches="+plan.areas.Count);}
[MenuItem("Anseong/Art/Apply Factory Paving")]
public static void ApplyFactoryPaving(){EditorSceneManager.OpenScene(Scene);Folder(FactoryPavingFolder);var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/QuaySurfaceDesign/04_CraneApron_LightSlabs.mat");string[] names={"01_General_LightAsphalt","02_Production_LargeConcrete","03_Process_MidConcrete","04_Utility_InterlockingPavers","05_Dispatch_LightConcrete"};Color[] colors={new Color(.80f,.85f,.88f),new Color(.94f,.97f,.96f),new Color(.79f,.85f,.85f),new Color(.85f,.88f,.83f),new Color(.99f,1.02f,1.03f)};var mats=new Material[5];for(int i=0;i<5;i++){var m=new Material(source){name=names[i]};m.SetColor("_BaseColor",colors[i]);m.SetFloat("_Pattern",i==0?1:i==3?2:0);m.SetFloat("_SlabSize",i==1?8:i==2?10:5);m.SetFloat("_TileSize",i==0?1.2f:i==3?3:8);m.SetFloat("_JointStrength",i==0?0:i==3?.16f:.12f);m.SetFloat("_DustStrength",.018f);m.SetFloat("_Contrast",.48f);m.SetFloat("_Brightness",1.12f);var oldMat=AssetDatabase.LoadAssetAtPath<Material>(FactoryPavingFolder+"/"+names[i]+".mat");if(oldMat){Object.DestroyImmediate(m);mats[i]=oldMat;}else{AssetDatabase.CreateAsset(m,FactoryPavingFolder+"/"+names[i]+".mat");mats[i]=m;}}
var data=JsonUtility.FromJson<RoadResult>(File.ReadAllText("Tools/FactoryPavingDesign/factory_paving_result.json"));var v=new List<Vector3>();var ind=new List<int>[5];for(int i=0;i<5;i++)ind[i]=new List<int>();foreach(var layer in data.layers)for(int j=0;j<layer.xy.Length;j+=6){int n=v.Count;for(int k=0;k<3;k++)v.Add(new Vector3(layer.xy[j+k*2],.024f,layer.xy[j+k*2+1]));ind[layer.channel].AddRange(new[]{n,n+2,n+1});}var mesh=new Mesh{name="FactoryFivePavingZones",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(v);mesh.subMeshCount=5;for(int i=0;i<5;i++)mesh.SetTriangles(ind[i],i);mesh.RecalculateNormals();mesh.RecalculateBounds();var oldMesh=AssetDatabase.LoadAssetAtPath<Mesh>(FactoryPavingFolder+"/FactoryFivePavingZones.asset");if(oldMesh){EditorUtility.CopySerialized(mesh,oldMesh);Object.DestroyImmediate(mesh);mesh=oldMesh;EditorUtility.SetDirty(mesh);}else AssetDatabase.CreateAsset(mesh,FactoryPavingFolder+"/FactoryFivePavingZones.asset");var root=GameObject.Find("Factory_FivePavingZones");if(!root){root=new GameObject("Factory_FivePavingZones");root.AddComponent<MeshFilter>();root.AddComponent<MeshRenderer>();}root.GetComponent<MeshFilter>().sharedMesh=mesh;root.GetComponent<MeshRenderer>().sharedMaterials=mats;File.WriteAllText(FactoryPavingFolder+"/DesignGuide.md",data.report+"\nFive material slots: light asphalt general circulation; large-panel production concrete; medium-grey process pads; utility maintenance pavers; bright dispatch/silo concrete. Derived from actual active prefab footprints, clipped to the existing L-shaped production boundary, road surfaces subtracted. Same compressed texture and quay surface shader reused; one additional combined floor renderer, no colliders or runtime scripts. Surface height0.024m below road0.038m. Includes adjoining transition strips X-215 to-151 and rear transition Z269–445, joining existing industrial paving to the battle-yard boundary. Existing assets, sea, mountains and battle yard unchanged. VR performance not measured.\n");AssetDatabase.SaveAssets();AssetDatabase.Refresh();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);ShaderUtil.allowAsyncCompilation=false;Capture(Camera.main,"FactoryPaving_Main");Debug.Log("FACTORY_PAVING_PASS types=5 vertices="+v.Count+" newTextures=0 newShaders=0");}
